export const getDecideKycUrl = (id: string,) => {




  return `/api/v1/admin/kyc/${id}/decision`
}

/**
 * @summary Applies a KYC decision
 */
export const decideKyc = async (id: string,
    decisionInput: DecisionInput, options?: Parameters<typeof customFetch>[1]): Promise<OperationResult> => {

  return customFetch<OperationResult>(getDecideKycUrl(id),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(decisionInput)
  }
);}





export const getDecideKycMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof decideKyc>>, TError,{id: string;data: BodyType<DecisionInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof decideKyc>>, TError,{id: string;data: BodyType<DecisionInput>}, TContext> => {

const mutationKey = ['decideKyc'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof decideKyc>>, {id: string;data: BodyType<DecisionInput>}> = (props) => {
          const {id,data} = props ?? {};

          return  decideKyc(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type DecideKycMutationResult = NonNullable<Awaited<ReturnType<typeof decideKyc>>>
    export type DecideKycMutationBody = BodyType<DecisionInput>
    export type DecideKycMutationError = ErrorType<unknown>

    /**
 * @summary Applies a KYC decision
 */
export const useDecideKyc = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof decideKyc>>, TError,{id: string;data: BodyType<DecisionInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof decideKyc>>,
        TError,
        {id: string;data: BodyType<DecisionInput>},
        TContext
      > => {
      return useMutation(getDecideKycMutationOptions(options));
    }

